                        .HasComment("This is a boolean that will determine if the volume is bullish or bearish, if the volume is bullish it will be true, if it is bearish it will be false");

                    b.Property<decimal>("PriceValue")
                        .HasColumnType("DECIMAL(6, 2)")
                        .HasComment("This is the current price for 1 share of a stock");

                    b.Property<long>("Volume")
                        .HasColumnType("bigint")
                        .HasComment("This is how much shares of a stock were bought/sold in a specific time span (e.g. a day, a week, a month,)");

                    b.HasKey("Id");

                    b.HasIndex("EventId")
                        .IsUnique();

